#include <Cellerator/compiler/backend/nvcc/implement_relocatable_device_code_and_device_linking_v1.hh>
#include <set>
namespace cellerator::compiler::backend::nvcc::v1 {
std::optional<device_link_plan> plan_device_link(const device_link_request&r,device_link_status*s) noexcept{auto set=[&](auto v){if(s)*s=v;};if(r.objects.size()<2){set(device_link_status::insufficient_objects);return{};}if(r.linked_object.empty()||r.registration_object.empty()){set(device_link_status::invalid_path);return{};}if(r.architectures.empty()){set(device_link_status::missing_architecture);return{};}std::set<std::string>defs;for(const auto&o:r.objects){if(o.path.empty()){set(device_link_status::invalid_path);return{};}for(const auto&d:o.definitions)if(!defs.insert(d).second){set(device_link_status::duplicate_symbol);return{};}}for(const auto&o:r.objects)for(const auto&x:o.references)if(!defs.count(x)){set(device_link_status::unresolved_symbol);return{};}device_link_plan p;for(const auto&o:r.objects)p.compile_actions.push_back("nvcc -dc "+o.path);p.nvlink_argv={"nvcc","-dlink"};for(const auto&o:r.objects)p.nvlink_argv.push_back(o.path);for(const auto&l:r.libraries)p.nvlink_argv.push_back("-l"+l);p.nvlink_argv.insert(p.nvlink_argv.end(),{"-o",r.linked_object});p.registration_action="nvcc -c "+r.linked_object+" -o "+r.registration_object;set(device_link_status::ok);return p;}
}
